-- Uruguay: milestones + English translations. Hand-written, following
-- the Pakistan/Ecuador pattern. Six milestones, live-researched against
-- DGI's own site (efactura.dgi.gub.uy, gub.uy), IMPO (Uruguay's official
-- legal gazette/database), the CIAT country profile, and industry
-- tax-technology advisories:
--
-- 1. uy-cfe-decree-2012 (2012-02-08, anchor, off-board, mandate_scope=
--    'none') -- Decreto 36/012, the founding legal decree creating the
--    CFE regime -- foundational, not itself a compliance deadline.
-- 2. uy-cfe-framework-2012 (2012-05-08, off-board, mandate_scope='none')
--    -- Resolución DGI 798/012, the operational/technical framework that
--    opened voluntary and first-mandatory incorporation.
-- 3. uy-phased-rollout-2014-2019 (2014-01-01, off-board, mandate_scope=
--    'b2b') -- the multi-year phased mandatory rollout by taxpayer
--    revenue tier (Unidades Indexadas thresholds), 2014 through 2019 --
--    a real, binding mandate for each successive tier, but represented
--    as a single anchor entry since it unfolded across many individual
--    DGI resolutions rather than one dated event.
-- 4. uy-deadline-extension-2023 (2023-12-01, off-board, mandate_scope=
--    'none') -- Resolución DGI 2548/023, which set the final deadline
--    (31 December 2024) for the remaining taxpayer population --
--    procedural/deadline-setting, not itself the moment of obligation.
-- 5. uy-universal-mandate-2025 (2025-01-01, on-board, mandate_scope=
--    'b2b') -- the flagship/headline milestone: universal mandatory CFE
--    issuance for essentially all VAT taxpayers, closing the exemption
--    window DGI had maintained since 2012.
-- 6. uy-cfe-v25-controls-2026 (2026-04-15, on-board, mandate_scope=
--    'none') -- CFE format v25.1's new mandatory cross-reference and
--    issuer-validation controls, part of DGI's ongoing schema evolution
--    rather than a scope expansion.
--
-- mandate_scope classification: Uruguay's CFE mandate has always been a
-- general sales-documentation requirement covering B2B, B2C, and B2G
-- transactions alike -- there is no B2G-only phase in its history, so
-- every scope-bearing milestone here is classified 'b2b' per
-- ADDING-A-COUNTRY.md's definition (a mandate requiring structured
-- e-invoicing between businesses), with purely technical/procedural
-- milestones classified 'none'.

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'uy-cfe-decree-2012', id, '2012-02-08', 1, 'https://www.impo.com.uy/bases/decretos/36-2012', 0, '[]', NULL, 'none' FROM countries WHERE code = 'UY';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-decree-2012', 'en', 'Decreto 36/012 creates Uruguay''s CFE (Comprobante Fiscal Electrónico) regime', 'On 8 February 2012, Uruguay''s executive branch promulgated Decreto 36/012, the founding decree of the Comprobante Fiscal Electrónico (CFE) system: it defines the CFE itself, obliges included taxpayers to document their sales exclusively through authorized CFE, requires a valid electronic certificate and signature, and establishes that CFE non-compliance is sanctioned under Uruguay''s general tax-documentation penalty regime rather than a CFE-specific fine schedule. This decree is the legal foundation for everything that followed -- the DGI-run system built on top of it is one of the oldest mandatory e-invoicing regimes in Latin America.', '["No action required for this historical milestone -- included for context ahead of the entries below", "If you''re researching Uruguay''s legal e-invoicing framework, Decreto 36/012 (and its Art. 17 penalty cross-reference) is the foundational text to start from"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'uy-cfe-framework-2012', id, '2012-05-08', 0, 'https://www.impo.com.uy/bases/resoluciones-dgi-interes-general/798-2012', 0, '[]', NULL, 'none' FROM countries WHERE code = 'UY';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-framework-2012', 'en', 'Resolución DGI 798/012 builds the operational framework and opens voluntary incorporation', 'Issued 8 May 2012, Resolución de Interés General 798/012 operationalized Decreto 36/012: it defined the CFE document types (e-Factura, e-Ticket, credit/debit notes, e-Remito, and more), set the XML-plus-electronic-signature format, required daily consolidated reporting to DGI, and established contingency receipts for system outages. This resolution is what let DGI begin designating taxpayers for voluntary and, later, compulsory incorporation -- the mechanism used for every mandatory wave that followed.', '["No action required for this historical milestone -- it establishes the technical/legal machinery that later mandatory waves (see below) built on", "If you''re evaluating Uruguay''s CFE document types, this resolution is where e-Factura, e-Ticket, and the other core types were first defined"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'uy-phased-rollout-2014-2019', id, '2014-01-01', 0, 'https://www.ciat.org/Biblioteca/Estudios/2018_FE/cap1-8_Uruguay.pdf', 0, '[]', NULL, 'b2b' FROM countries WHERE code = 'UY';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-phased-rollout-2014-2019', 'en', 'DGI phases in mandatory CFE adoption by taxpayer revenue tier, 2014-2019', 'From 2014, DGI layered compulsory CFE incorporation on top of voluntary enrollment, starting with large taxpayers (Grandes Contribuyentes), CEDE-classified enterprises, and duty-free operators, then extending in successive annual waves keyed to each taxpayer''s prior-year sales volume in Unidades Indexadas (UI): taxpayers with roughly UI 30 million/15 million in 2015 sales were brought in during 2016, UI 7 million/4 million (2016 sales) in 2017, UI 2.5 million/1.5 million (2017 sales) in 2018, and UI 750,000/305,000 (2018 sales) in 2019 -- each wave pulling in thousands more taxpayers. By the end of 2016, DGI counted over 5,000 cumulative electronic issuers processing more than 1.28 billion CFE a year.', '["If your business was designated into an earlier wave, confirm your CFE issuance has kept pace with any subsequent DGI resolution updating the technical format", "This phased-by-revenue-tier approach is the model DGI used before moving to the near-universal deadlines described in the milestones below -- useful context if you''re researching Uruguay''s history rather than its current requirements"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'uy-deadline-extension-2023', id, '2023-12-01', 0, 'https://www.impo.com.uy/bases/resoluciones-dgi/2548-2023', 0, '[]', NULL, 'none' FROM countries WHERE code = 'UY';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-deadline-extension-2023', 'en', 'Resolución DGI 2548/023 sets the final deadline for universal CFE adoption', 'Approved 30 November 2023 and published 1 December 2023, Resolución DGI 2548/023 extended an earlier compulsory-incorporation deadline (set by the companion Resolución 2389/023): taxpayers already reached by that designation got until 31 December 2024 to become electronic issuers, and anyone newly registering for VAT between 1 May 2024 and 31 December 2024 had to be issuing electronically before 1 January 2025. This resolution set the deadline that the universal-mandate milestone below actually delivers.', '["No action required for this historical milestone -- it sets the deadline that the next entry describes taking effect", "If your business registered for VAT during 2024, confirm which deadline in this resolution applied to you specifically"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'uy-universal-mandate-2025', id, '2025-01-01', 0, 'https://www.gub.uy/direccion-general-impositiva/comunicacion/noticias/facturacion-electronica-incorporacion-restantes-contribuyentes-iva', 1, '[{"label": "DGI e-Factura portal", "url": "https://www.efactura.dgi.gub.uy/"}]', NULL, 'b2b' FROM countries WHERE code = 'UY';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-universal-mandate-2025', 'en', 'Universal mandatory CFE issuance takes effect, closing the exemption window', 'In an official communiqué published 28 November 2024, DGI announced that from 1 January 2025, essentially all remaining VAT contributors -- including those under the "IVA Mínimo" (minimum VAT) regime -- became electronic issuers, closing the exemption window the agency had maintained in various forms since 2012. A short, defined list of exceptions remains: taxpayers whose activity is exclusively agricultural with annual income below UI 4,000,000, VAT taxpayers performing only value-added construction services, non-resident income tax (IRNR) taxpayers, fully VAT-exempt activity outside free trade zones, and Uruguay''s simplified micro-enterprise regimes (Monotributo, Monotributo Social MIDES, and Aporte Único). DGI''s own announcement reported that electronic invoicing already reached 98% of documentation issued in the country at that point -- this is the closing phase of a digitalization process DGI began more than a decade earlier, not a sudden new requirement.', '["If your business wasn''t already issuing CFE, confirm you''re now registered as an electronic issuer -- the exemption window that may have applied to you closed on 1 January 2025", "Check whether you fall into one of the narrow remaining exemptions (small-scale agriculture, construction value-add, IRNR, full VAT exemption, or a simplified micro-enterprise regime) before assuming the mandate applies to you"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'uy-cfe-v25-controls-2026', id, '2026-04-15', 0, 'https://www.efactura.dgi.gub.uy/', 1, '[{"label": "DGI e-Factura portal", "url": "https://www.efactura.dgi.gub.uy/"}]', NULL, 'none' FROM countries WHERE code = 'UY';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-v25-controls-2026', 'en', 'CFE format v25.1''s new mandatory validation controls take effect', 'DGI''s CFE technical specification has been revised repeatedly over the system''s history -- most recently to versions 25 and 25.1. New data fields and validations across several schema zones entered production on 3 March 2026, and stricter mandatory controls followed on 15 April 2026 for invoice cross-reference and traceability data (currency and exchange-rate fields) and for authorized-representative and issuer RUC validation. This is routine technical schema evolution layered on top of the existing mandate, not an expansion of who must issue CFE.', '["Confirm your invoicing software or service provider has implemented CFE format v25.1''s field and validation changes ahead of the 15 April 2026 mandatory-controls date", "If you use a third-party e-invoicing provider, ask them directly whether they''ve certified against v25.1 rather than assuming compatibility"]');
